liquid:
{%- assign valid = true -%}
{%- assign inputs = nil -%}
{%- assign selected = '' | split: '' -%}
{%- assign hasInputs = apiEaseParameters | has_key: 'liquidParams' -%}
{%- if hasInputs -%}
  {%- assign inputs = apiEaseParameters.liquidParams -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'products' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.products | is_type: 'array' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs | has_key: 'prefix' -%}
{%- endif -%}
{%- if valid -%}
  {%- assign valid = inputs.prefix | is_type: 'string' -%}
{%- endif -%}
{%- if valid -%}
  {%- if inputs.prefix == '' -%}{%- assign valid = false -%}{%- endif -%}
{%- endif -%}
{%- assign error = 'products must be an array and prefix must be a nonempty string; both fields are required.' -%}
{%- if valid -%}
  {%- for item in inputs.products -%}
    {%- assign valid = item | has_key: 'title' -%}
    {%- assign error = 'Each products item must be an object with a valid title field.' -%}
    {%- if valid -%}
      {%- call {"requestId":"match-title-prefix","liquidParamsEmbedded":{"title":{{ item.title | json }},"prefix":{{ inputs.prefix | json }}}} as matcherResult -%}
      {%- assign error = 'The match-title-prefix call failed or returned an unusable result.' -%}
      {%- assign valid = matcherResult | has_key: 'status' -%}
      {%- if valid -%}
        {%- assign valid = matcherResult.status | is_type: 'integer' -%}
      {%- endif -%}
      {%- if valid -%}
        {%- if matcherResult.status < 200 or matcherResult.status >= 300 -%}{%- assign valid = false -%}{%- endif -%}
      {%- endif -%}
      {%- if valid -%}
        {%- assign valid = matcherResult | has_key: 'data' -%}
      {%- endif -%}
      {%- if valid -%}
        {%- assign hasSuccess = matcherResult.data | has_key: 'success' -%}
        {%- assign hasMatches = matcherResult.data | has_key: 'matches' -%}
        {%- assign hasError = matcherResult.data | has_key: 'error' -%}
        {%- unless hasSuccess and hasMatches and hasError -%}{%- assign valid = false -%}{%- endunless -%}
      {%- endif -%}
      {%- if valid -%}
        {%- assign successIsBoolean = matcherResult.data.success | is_type: 'boolean' -%}
        {%- assign matchesIsBoolean = matcherResult.data.matches | is_type: 'boolean' -%}
        {%- assign errorIsNull = matcherResult.data.error | is_type: 'null' -%}
        {%- unless successIsBoolean and matchesIsBoolean and errorIsNull and matcherResult.data.success == true -%}{%- assign valid = false -%}{%- endunless -%}
      {%- endif -%}
      {%- if valid -%}
        {%- if matcherResult.data.matches -%}
          {%- assign singleton = inputs.products | slice: forloop.index0, 1 -%}
          {%- assign selected = selected | concat: singleton -%}
        {%- endif -%}
      {%- endif -%}
    {%- endif -%}
    {%- unless valid -%}{%- break -%}{%- endunless -%}
  {%- endfor -%}
{%- endif -%}
{%- if valid -%}
{"success":true,"products":{{ selected | json }},"error":null}
{%- else -%}
{"success":false,"products":[],"error":{{ error | json }}}
{%- endif -%}
